STATIC = {
    'css/style.css': ':root{\n  --cream:#F7F9FA;\n  --cream-2:#EDF1F3;\n  --navy:#4A2330;\n  --navy-2:#61303D;\n  --teal:#7B1F2B;\n  --teal-dark:#641821;\n  --amber:#E0A72E;\n  --amber-dark:#C58A1B;\n  --ink:#242B2F;\n  --ink-soft:#5C6A72;\n  --line:#DCE2E6;\n}\n\n*{box-sizing:border-box;}\nhtml{scroll-behavior:smooth;}\n[id]{scroll-margin-top:84px;}\nbody{\n  margin:0;\n  background:var(--cream);\n  color:var(--ink);\n  font-family:\'Work Sans\',sans-serif;\n  line-height:1.6;\n  display:flex;\n  flex-direction:column;\n  min-height:100vh;\n}\nmain{flex:1;}\nh1,h2,h3,h4{\n  font-family:\'Fraunces\',serif;\n  color:var(--navy);\n  margin:0;\n  font-weight:500;\n}\na{color:inherit;text-decoration:none;transition:color .2s;}\na:hover{color:var(--teal);}\nimg{max-width:100%;display:block;}\n.wrap{max-width:1080px;margin:0 auto;padding:0 28px;}\n\n/* ===== Buttons ===== */\n.btn{\n  display:inline-flex;align-items:center;gap:10px;\n  padding:12px 24px;border-radius:3px;\n  font-family:\'Work Sans\',sans-serif;font-size:15px;font-weight:500;\n  cursor:pointer;border:1px solid transparent;\n  transition:all .2s;text-align:center;\n}\n.btn-primary{background:var(--teal);color:var(--cream);}\n.btn-primary:hover{background:var(--teal-dark);color:var(--cream);}\n.btn-secondary,.btn-outline{\n  border:1px solid var(--navy);color:var(--navy);background:transparent;\n  padding:12px 24px;border-radius:3px;\n  font-family:\'Work Sans\',sans-serif;font-size:15px;font-weight:500;\n  display:inline-flex;align-items:center;gap:10px;text-align:center;cursor:pointer;\n  line-height:1.5;transition:all .2s;\n}\n.btn-secondary:hover,.btn-outline:hover{background:var(--navy);color:var(--cream);}\n.btn-gold{background:var(--amber);color:var(--navy);}\n.btn-gold:hover{background:var(--amber-dark);color:var(--navy);}\n.btn-wa{background:var(--navy);color:var(--cream);}\n.btn-wa:hover{background:var(--navy-2);color:var(--cream);}\n.btn-danger{background:#b3261e;color:#fff;}\n.btn-danger:hover{background:#8f1d17;color:#fff;}\n.btn-success{background:#7B1F2B;color:#fff;}\n.btn-success:hover{background:#641821;color:#fff;}\n.btn-info{background:var(--navy-2);color:var(--cream);}\n.btn-info:hover{background:var(--navy);color:var(--cream);}\n.btn-lg{padding:14px 30px;font-size:16px;}\n.btn-sm{padding:8px 18px;font-size:13px;}\n.btn-xs{padding:4px 12px;font-size:12px;}\n.btn-block{display:flex;justify-content:center;width:100%;}\n.btn-row{display:flex;gap:10px;flex-wrap:wrap;}\n\n/* ===== Navbar (mockup) ===== */\nheader{\n  position:sticky;top:0;z-index:20;\n  background:rgba(247,249,250,0.92);\n  backdrop-filter:blur(6px);\n  border-bottom:1px solid var(--line);\n}\nnav{display:flex;align-items:center;justify-content:space-between;padding:16px 0;}\n.brand{display:flex;align-items:center;gap:10px;font-family:\'Fraunces\',serif;font-size:20px;color:var(--navy);}\n.brand svg{flex-shrink:0;}\n.nav-links{display:flex;gap:32px;font-size:15px;color:var(--ink-soft);align-items:center;list-style:none;margin:0;padding:0;}\n.nav-links li{margin:0;}\n.nav-links a:hover,\n.nav-links a.active{color:var(--navy);}\n.nav-links a{color:var(--ink-soft);font-size:15px;}\n.nav-links a.active{color:var(--navy);font-weight:500;}\n.nav-links a.nav-cta,.nav-cta{\n  background:var(--navy);color:#fff;\n  padding:10px 20px;border-radius:3px;\n  font-size:14px;font-weight:500;\n  display:inline-flex;align-items:center;gap:8px;\n}\n.nav-links a.nav-cta:hover,.nav-cta:hover{background:var(--navy-2);color:#fff;}\n.nav-toggle{\n  display:none;background:none;border:none;font-size:24px;\n  color:var(--navy);cursor:pointer;\n}\n\n@media(max-width:860px){\n  .nav-links{\n    display:none;flex-direction:column;position:absolute;top:100%;left:0;right:0;\n    background:var(--cream);border-bottom:1px solid var(--line);\n    padding:18px 28px;gap:14px;box-shadow:0 10px 24px rgba(0,0,0,.06);\n  }\n  .nav-links.show{display:flex;}\n  nav{position:relative;}\n  .nav-toggle{display:block;}\n}\n\n/* ===== Hero (background image) ===== */\n.hero{\n  padding:120px 0 110px;\n  text-align:center;\n  color:#fff;\n  background:\n    linear-gradient(180deg, rgba(8,5,7,.62) 0%, rgba(8,5,7,.30) 45%, rgba(8,5,7,.62) 100%),\n    url(\'https://images.pexels.com/photos/5894278/pexels-photo-5894278.jpeg?auto=compress&cs=tinysrgb&w=1920\') center/cover no-repeat;\n}\n.hero .eyebrow-line{justify-content:center;color:rgba(255,255,255,.85);}\n.hero .eyebrow-line .dash{background:var(--amber);}\n.hero h1{color:#fff;font-size:clamp(36px,5vw,54px);line-height:1.12;letter-spacing:-.01em;}\n.hero h1 .accent{color:var(--amber);font-style:italic;}\n.hero p.lede{margin:22px auto 0;font-size:17px;color:rgba(255,255,255,.9);max-width:46ch;}\n.hero-actions{display:flex;gap:14px;margin-top:32px;flex-wrap:wrap;justify-content:center;}\n.hero .btn-primary{background:var(--amber);color:var(--navy);}\n.hero .btn-primary:hover{background:var(--amber-dark);color:#fff;}\n.hero .btn-secondary{border-color:#fff;color:#fff;}\n.hero .btn-secondary:hover{background:#fff;color:var(--navy);}\n.hero-stats{\n  display:flex;justify-content:center;gap:56px;flex-wrap:wrap;\n  margin-top:52px;padding-top:28px;border-top:1px solid rgba(255,255,255,.22);\n}\n.hero-stats div{text-align:center;}\n.hero-stats .num{font-family:\'Fraunces\',serif;font-size:28px;color:#fff;font-weight:600;line-height:1.2;}\n.hero-stats .lbl{font-size:12.5px;color:rgba(255,255,255,.8);letter-spacing:.3px;}\n\n/* ===== Trustline ===== */\n.trustline{border-top:1px solid var(--line);border-bottom:1px solid var(--line);padding:20px 0;background:var(--cream-2);}\n.trustline .wrap{\n  display:flex;justify-content:space-between;gap:0;flex-wrap:wrap;\n  font-size:14px;color:var(--ink-soft);text-align:center;\n}\n.trustline .wrap > div{flex:1;padding:4px 22px;}\n.trustline .wrap > div + div{border-left:1px solid var(--line);}\n.trustline strong{color:var(--navy);font-weight:600;}\n@media(max-width:700px){\n  .trustline .wrap{gap:10px 0;}\n  .trustline .wrap > div{flex:1 1 100%;padding:4px 0;}\n  .trustline .wrap > div + div{border-left:none;}\n}\n\n/* ===== Sections ===== */\n.section{padding:84px 0;}\n.section-head{max-width:56ch;margin:0 auto 46px;text-align:center;}\n.section-head h2{font-size:32px;line-height:1.2;}\n.section-head h2::after{\n  content:\'\';display:block;width:44px;height:2px;border-radius:2px;\n  background:var(--teal);margin:14px auto 0;\n}\n.section-head p{color:var(--ink-soft);margin-top:12px;font-size:16px;}\n@media(max-width:600px){.section-head h2{font-size:26px;}}\n.section-tint{background:var(--cream-2);}\n\n/* ===== Layanan ===== */\n.services{display:grid;grid-template-columns:repeat(3,1fr);gap:22px;}\n@media(max-width:900px){.services{grid-template-columns:repeat(2,1fr);}}\n@media(max-width:600px){.services{grid-template-columns:1fr;}}\n.service-card{\n  background:var(--cream-2);\n  border:1px solid var(--line);\n  border-radius:6px;\n  padding:28px;\n  display:flex;flex-direction:column;gap:8px;\n  transition:box-shadow .25s, transform .25s, border-color .25s;\n}\n.service-card:hover{box-shadow:0 12px 26px rgba(31,54,50,.08);border-color:#c9d3d9;transform:translateY(-3px);}\n.service-card .icon{width:40px;height:40px;margin-bottom:14px;}\n.service-card h3{font-size:19px;margin-bottom:6px;}\n.service-card p{font-size:14.5px;color:var(--ink-soft);margin:0 0 12px;flex:1;}\n.service-card .price{\n  font-size:14px;color:var(--teal);font-weight:600;\n  border-top:1px solid var(--line);padding-top:12px;margin-top:auto;\n}\n\n/* ===== Galeri ===== */\n.gallery-grid{\n  display:grid;grid-template-columns:repeat(4,1fr);gap:14px;\n}\n@media(max-width:900px){.gallery-grid{grid-template-columns:repeat(3,1fr);}}\n@media(max-width:640px){.gallery-grid{grid-template-columns:repeat(2,1fr);}}\n.gallery-grid.large{grid-template-columns:repeat(3,1fr);}\n@media(max-width:640px){.gallery-grid.large{grid-template-columns:repeat(2,1fr);}}\n@media(max-width:420px){.gallery-grid.large{grid-template-columns:1fr;}}\n.gallery-item{\n  position:relative;aspect-ratio:1;border-radius:4px;\n  display:flex;align-items:center;justify-content:center;\n  overflow:hidden;\n}\n.gallery-item img{width:100%;height:100%;object-fit:cover;transition:transform .4s;}\n.gallery-item:hover img{transform:scale(1.05);}\n.gallery-item .gcaption{\n  position:absolute;bottom:0;left:0;right:0;\n  background:linear-gradient(transparent,rgba(74,33,48,.85));\n  color:var(--cream);font-size:13px;text-align:center;padding:30px 10px 10px;\n  opacity:0;transition:opacity .3s;\n}\n.gallery-item:hover .gcaption{opacity:1;}\n.gallery-item.ph{\n  color:rgba(247,249,250,.75);font-size:13px;text-align:center;padding:10px;\n}\n.gallery-item.ph:nth-child(1){background:linear-gradient(135deg,#4A2330,#61303D);}\n.gallery-item.ph:nth-child(2){background:linear-gradient(135deg,#7B1F2B,#641821);}\n.gallery-item.ph:nth-child(3){background:linear-gradient(135deg,#A0465A,#8A3A4A);}\n.gallery-item.ph:nth-child(4){background:linear-gradient(135deg,#E0A72E,#C58A1B);}\n.gallery-item.ph:nth-child(5){background:linear-gradient(135deg,#8A4A58,#6E3240);}\n.gallery-item.ph:nth-child(6){background:linear-gradient(135deg,#61303D,#4A2330);}\n.gallery-item.ph:nth-child(7){background:linear-gradient(135deg,#641821,#4D1C26);}\n.gallery-item.ph:nth-child(8){background:linear-gradient(135deg,#C58A1B,#9E6B12);}\n\n/* ===== Tentang (mockup) ===== */\n.about{display:grid;grid-template-columns:.8fr 1.2fr;gap:56px;align-items:center;}\n@media(max-width:820px){.about{grid-template-columns:1fr;}}\n.about-visual{\n  background:var(--cream-2);border:1px solid var(--line);border-radius:4px;\n  aspect-ratio:1;display:flex;align-items:center;justify-content:center;\n}\n.about h2{font-size:30px;margin-bottom:18px;}\n.about p{color:var(--ink-soft);font-size:16px;margin-bottom:14px;max-width:52ch;}\n.about-quote{\n  border-left:2px solid var(--teal);padding-left:18px;margin-top:22px;\n  font-family:\'Fraunces\',serif;font-style:italic;color:var(--navy);font-size:18px;\n}\n\n/* ===== Testimoni ===== */\n.testimonials{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;}\n@media(max-width:900px){.testimonials{grid-template-columns:repeat(2,1fr);}}\n@media(max-width:600px){.testimonials{grid-template-columns:1fr;}}\n.t-card{background:var(--cream);border:1px solid var(--line);border-radius:6px;padding:26px;display:flex;flex-direction:column;}\n.t-card p{font-size:15px;color:var(--ink);margin:0 0 16px;}\n.t-name{font-size:13.5px;color:var(--ink-soft);margin-top:auto;}\n\n/* ===== CTA band (mockup) ===== */\n.cta-band{\n  background:var(--navy);color:var(--cream);border-radius:6px;\n  padding:56px 44px;display:flex;justify-content:space-between;align-items:center;gap:30px;flex-wrap:wrap;\n}\n.cta-band h2{color:var(--cream);font-size:28px;max-width:24ch;}\n.cta-band .btn-primary{background:var(--amber);color:var(--navy);}\n.cta-band .btn-primary:hover{background:var(--amber-dark);color:#fff;}\n\n/* ===== Footer ===== */\nfooter{padding:48px 0 40px;border-top:1px solid var(--line);background:var(--cream-2);}\n.footer-grid{\n  display:grid;grid-template-columns:repeat(3,1fr);gap:32px;\n  font-size:14px;color:var(--ink-soft);align-items:start;\n}\n@media(max-width:760px){.footer-grid{grid-template-columns:1fr;gap:24px;}}\n.footer-brand{font-family:\'Fraunces\',serif;color:var(--navy);font-size:18px;margin-bottom:8px;}\n.footer-grid .more{display:flex;flex-direction:column;gap:8px;align-items:flex-start;}\n.footer-bottom{margin-top:28px;padding-top:18px;border-top:1px solid var(--line);text-align:center;font-size:13px;color:var(--ink-soft);}\n\n/* ===== Floating WA (mockup) ===== */\n.wa-float{\n  position:fixed;bottom:22px;right:22px;\n  background:var(--navy);color:var(--cream);\n  width:56px;height:56px;border-radius:50%;\n  display:flex;align-items:center;justify-content:center;\n  box-shadow:0 4px 14px rgba(0,0,0,.18);\n  z-index:30;\n  transition:background .2s, transform .2s;\n}\n.wa-float:hover{background:var(--teal);color:var(--cream);transform:translateY(-2px);}\n\n/* ===== Eyebrow line ===== */\n.eyebrow-line{\n  display:flex;align-items:center;gap:10px;margin-bottom:22px;\n  color:var(--ink-soft);font-size:14px;\n}\n.eyebrow-line .dash{width:28px;height:1px;background:var(--teal);}\n\n/* ===== Page header (subpages) ===== */\n.page-hero{\n  background:var(--cream-2);border-bottom:1px solid var(--line);\n  padding:52px 0 44px;text-align:center;\n}\n.page-hero .eyebrow-line{justify-content:center;margin-bottom:12px;}\n.page-hero h1{font-size:clamp(30px,4.5vw,42px);line-height:1.15;}\n.page-hero p{color:var(--ink-soft);font-size:16px;margin:12px auto 0;max-width:54ch;}\n\n/* ===== Forms ===== */\n.form-wrap{max-width:680px;margin:0 auto;}\n.order-form{\n  background:var(--cream-2);border:1px solid var(--line);border-radius:4px;\n  padding:32px;\n}\n.form-row{display:grid;grid-template-columns:1fr 1fr;gap:20px;}\n.form-group{margin-bottom:20px;}\n.form-group label{display:block;font-size:14px;font-weight:500;margin-bottom:6px;color:var(--navy);}\n.req{color:var(--teal);}\n.form-group input[type="text"],\n.form-group input[type="tel"],\n.form-group input[type="date"],\n.form-group input[type="password"],\n.form-group input[type="file"],\n.form-group select,\n.form-group textarea{\n  width:100%;padding:12px 14px;\n  border:1px solid var(--line);border-radius:3px;\n  font-family:\'Work Sans\',sans-serif;font-size:14px;color:var(--ink);\n  background:var(--cream);\n  transition:border-color .2s, box-shadow .2s;\n}\n.form-group input:focus,\n.form-group select:focus,\n.form-group textarea:focus{\n  outline:none;border-color:var(--teal);\n  box-shadow:0 0 0 3px rgba(123,31,43,.14);\n}\n.form-group textarea{resize:vertical;}\n.checkbox-group{margin-bottom:16px;}\n.checkbox-label{display:flex;align-items:center;gap:8px;font-size:14px;cursor:pointer;}\n.checkbox-label input{width:16px;height:16px;accent-color:var(--teal);}\n.form-error{\n  background:#fef2f2;border:1px solid #fecaca;color:#b91c1c;\n  padding:12px 16px;border-radius:4px;margin-bottom:18px;font-size:14px;\n}\n.success-box{\n  background:var(--cream-2);border:1px solid var(--line);border-radius:6px;\n  padding:48px 32px;text-align:center;\n}\n.success-box i{font-size:54px;color:var(--teal);display:block;margin-bottom:16px;}\n.success-box h2{margin-bottom:10px;color:var(--navy);}\n.success-box p{color:var(--ink-soft);margin-bottom:10px;}\n.success-box .btn{margin:8px;}\n.wa-note{margin-top:12px;font-size:14px;}\n\n/* ===== Flash ===== */\n.flash-container{margin-top:16px;}\n.flash{padding:12px 16px;border-radius:4px;margin-bottom:10px;font-size:14px;}\n.flash-success{background:#f6e8e8;border:1px solid #e3c4c0;color:#7B1F2B;}\n.flash-error{background:#fef2f2;border:1px solid #fecaca;color:#b91c1c;}\n.flash-info{background:#f1e6ea;border:1px solid #e0c2cb;color:var(--navy);}\n\n/* ===== Empty / center buttons ===== */\n.center-btn{text-align:center;margin-top:36px;}\n.empty-state{text-align:center;color:var(--ink-soft);padding:40px 20px;grid-column:1/-1;width:100%;}\n.empty-state i{font-size:40px;color:var(--amber);display:block;margin-bottom:12px;}\n\n/* =========================================\n   ADMIN — sidebar layout\n   ========================================= */\n.admin-body{display:block;}\n\n/* Sidebar */\n.admin-sidebar{\n  position:fixed;top:0;bottom:0;left:0;width:252px;z-index:40;\n  background:var(--navy);color:#fff;\n  display:flex;flex-direction:column;\n  padding:26px 18px 18px;\n}\n.sidebar-brand{\n  display:flex;align-items:center;gap:10px;\n  font-family:\'Fraunces\',serif;font-size:19px;color:#fff;\n  padding:0 10px 20px;border-bottom:1px solid rgba(255,255,255,.1);margin-bottom:20px;\n}\n.sidebar-brand:hover{color:#fff;}\n.sidebar-label{\n  font-size:11px;font-weight:600;letter-spacing:1.2px;text-transform:uppercase;\n  color:rgba(255,255,255,.4);padding:0 12px;margin-bottom:8px;\n}\n.sidebar-nav{\n  display:flex;flex-direction:column;align-items:stretch;justify-content:flex-start;padding:0;\n}\n.sidebar-nav a{\n  display:flex;align-items:center;gap:11px;\n  padding:11px 12px;border-radius:6px;margin-bottom:4px;\n  font-size:14.5px;color:rgba(255,255,255,.78);\n  transition:background .2s,color .2s;\n}\n.sidebar-nav a svg{flex-shrink:0;}\n.sidebar-nav a:hover{color:#fff;background:rgba(255,255,255,.08);}\n.sidebar-nav a.active{color:#fff;background:var(--teal);font-weight:500;}\n.sidebar-nav a.active:hover{background:var(--teal-dark);}\n\n.sidebar-foot{\n  margin-top:auto;padding-top:18px;border-top:1px solid rgba(255,255,255,.1);\n  display:flex;flex-direction:column;gap:2px;font-size:14px;\n}\n.sidebar-foot a{\n  display:flex;align-items:center;gap:11px;\n  padding:11px 12px;border-radius:6px;\n  color:rgba(255,255,255,.78);\n}\n.sidebar-foot a svg{flex-shrink:0;}\n.sidebar-foot a:hover{color:#fff;background:rgba(255,255,255,.08);}\n.sidebar-foot .logout-link{color:#f8a8a2;}\n.sidebar-foot .logout-link:hover{color:#fff;background:#8f1d17;}\n\n.admin-main{background:var(--cream-2);margin-left:252px;min-height:100vh;}\n\n/* Top bar ponsel (membuka sidebar) */\n.admin-topbar{display:none;}\n.admin-sidebar-toggle{\n  background:transparent;border:none;color:#fff;cursor:pointer;\n  display:flex;align-items:center;padding:6px;margin:-6px;\n}\n\n@media(max-width:900px){\n  .admin-topbar{\n    display:flex;align-items:center;gap:14px;\n    padding:14px 20px;background:var(--navy);color:#fff;\n    position:sticky;top:0;z-index:35;\n  }\n  .admin-topbar-title{font-family:\'Fraunces\',serif;font-size:17px;}\n  .admin-sidebar{\n    transform:translateX(-105%);\n    transition:transform .28s ease;\n    box-shadow:none;\n  }\n  .admin-sidebar.open{transform:translateX(0);box-shadow:0 0 44px rgba(0,0,0,.35);}\n  .admin-main{margin-left:0;}\n}\n\n.admin-container{max-width:1080px;margin:0 auto;padding:36px 28px 60px;}\n.admin-page-title{font-size:28px;color:var(--navy);margin-bottom:2px;}\n.admin-page-sub{color:var(--ink-soft);margin-bottom:24px;font-size:14px;}\n.page-head-row{display:flex;justify-content:space-between;align-items:flex-start;flex-wrap:wrap;gap:12px;}\n\n/* Admin login */\n.admin-login-page{\n  min-height:100vh;display:flex;align-items:center;justify-content:center;\n  background:var(--navy);padding:30px 20px;\n}\n.admin-login-box{\n  background:var(--cream);border-radius:6px;padding:40px 36px;\n  width:100%;max-width:400px;box-shadow:0 20px 50px rgba(0,0,0,.35);\n}\n.admin-login-brand{justify-content:center;font-size:22px;margin-bottom:8px;display:flex;}\n.admin-login-box h1{text-align:center;font-size:26px;font-family:\'Work Sans\',sans-serif;font-weight:600;margin-bottom:2px;}\n.admin-login-sub{text-align:center;color:var(--ink-soft);font-size:14px;margin-bottom:24px;}\n.admin-login-back{text-align:center;margin-top:18px;font-size:14px;}\n\n/* Stats */\n.stat-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin-bottom:30px;}\n.stat-card{\n  background:var(--cream);border:1px solid var(--line);border-radius:4px;\n  padding:20px 22px;display:flex;align-items:center;gap:16px;\n}\n.stat-card i{\n  font-size:11px;font-style:normal;font-weight:600;text-transform:uppercase;letter-spacing:.3px;\n  width:48px;height:48px;border-radius:4px;\n  display:flex;align-items:center;justify-content:center;text-align:center;line-height:1.2;\n}\n.stat-card h3{font-family:\'Work Sans\',sans-serif;font-size:26px;font-weight:600;line-height:1.1;color:var(--navy);}\n.stat-card p{font-size:13px;color:var(--ink-soft);}\n.stat-bar i{background:#f3e3be;color:#8c6415;}\n.stat-progress i{background:#e0e7f5;color:var(--navy-2);}\n.stat-done i{background:#f3e0e0;color:#7B1F2B;}\n.stat-cancel i{background:#fdecec;color:#b91c1c;}\n.stat-info i{background:#e6e0d3;color:var(--teal);}\n\n/* Panel & table */\n.panel{\n  background:var(--cream);border:1px solid var(--line);border-radius:4px;\n  padding:24px;margin-bottom:24px;\n}\n.panel-head{display:flex;justify-content:space-between;align-items:center;margin-bottom:18px;flex-wrap:wrap;gap:10px;}\n.panel-head h2{font-size:20px;font-family:\'Work Sans\',sans-serif;font-weight:600;}\n.table-responsive{overflow-x:auto;}\n.admin-table{width:100%;border-collapse:collapse;font-size:14px;}\n.admin-table th{\n  text-align:left;padding:10px 12px;background:var(--cream-2);\n  color:var(--ink-soft);font-weight:600;text-transform:uppercase;\n  font-size:12px;letter-spacing:.4px;border-bottom:2px solid var(--line);white-space:nowrap;\n}\n.admin-table td{padding:12px;border-bottom:1px solid var(--line);vertical-align:middle;}\n.admin-table tr:last-child td{border-bottom:none;}\n.admin-table tbody tr:hover td{background:var(--cream-2);}\n.empty-cell{text-align:center;padding:30px !important;color:var(--ink-soft);}\n.desc-cell{max-width:260px;color:var(--ink-soft);font-size:13px;}\n\n/* Badges */\n.badge{display:inline-block;padding:4px 12px;border-radius:20px;font-size:12px;font-weight:600;white-space:nowrap;}\n.badge-baru{background:#f3e3be;color:#8c6415;}\n.badge-dikerjakan{background:#e0e7f5;color:var(--navy-2);}\n.badge-selesai{background:#f3e0e0;color:#7B1F2B;}\n.badge-dibatalkan{background:#fdecec;color:#b91c1c;}\n.badge-kategori{background:var(--cream-2);color:var(--teal);}\n.badge-nonaktif{background:#fdecec;color:#b91c1c;}\n.badge-aktif{background:#f3e0e0;color:#7B1F2B;}\n\n/* Filter tabs */\n.filter-tabs{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px;}\n.filter-tab{\n  padding:7px 18px;border:1px solid var(--line);border-radius:30px;\n  font-size:13px;font-weight:500;color:var(--ink);background:var(--cream);\n}\n.filter-tab:hover{border-color:var(--navy);color:var(--navy);}\n.filter-tab.active{background:var(--navy);border-color:var(--navy);color:var(--cream);}\n\n/* Detail */\n.detail-grid{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin-bottom:20px;}\n.detail-list{display:flex;flex-direction:column;}\n.detail-row{display:flex;justify-content:space-between;padding:10px 0;border-bottom:1px solid var(--line);gap:12px;flex-wrap:wrap;}\n.detail-row:last-child{border-bottom:none;}\n.detail-label{color:var(--ink-soft);font-size:13px;font-weight:500;min-width:120px;}\n.detail-value{font-weight:500;display:flex;align-items:center;gap:8px;flex-wrap:wrap;}\n.detail-note{color:var(--ink-soft);white-space:pre-wrap;}\n.status-form{display:flex;gap:12px;align-items:center;flex-wrap:wrap;}\n.status-form select{\n  padding:12px 14px;border:1px solid var(--line);border-radius:3px;\n  font-family:\'Work Sans\',sans-serif;font-size:14px;min-width:220px;background:var(--cream);\n}\n.danger-zone{margin-top:10px;}\n\n/* Admin gallery */\n.admin-gallery-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:16px;}\n.admin-gallery-item{border:1px solid var(--line);border-radius:4px;overflow:hidden;background:var(--cream);}\n.admin-gallery-item img{width:100%;aspect-ratio:1/1;object-fit:cover;}\n.admin-gallery-info{padding:12px;display:flex;justify-content:space-between;align-items:center;gap:8px;}\n.admin-gallery-info p{font-size:13px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;}\n\n/* Quick actions */\n.quick-actions{display:flex;gap:12px;flex-wrap:wrap;}\n\n/* Edit row layanan */\n.edit-row td{background:var(--cream-2) !important;}\n.edit-form{box-shadow:none;background:transparent;border:none;padding:0;margin-bottom:12px;}\n.inline-delete{display:inline-block;}\n\n/* ===== Responsive ===== */\n@media(max-width:860px){\n  .detail-grid{grid-template-columns:1fr;}\n  .stat-grid{grid-template-columns:repeat(2,1fr);}\n}\n@media(max-width:600px){\n  .hero{padding:60px 0 52px;}\n  .form-row{grid-template-columns:1fr;gap:0;}\n  .order-form{padding:22px;}\n  .stat-grid{grid-template-columns:1fr;}\n  .cta-band{padding:40px 26px;}\n  .services{grid-template-columns:1fr;}\n}',
    'js/main.js': "document.addEventListener('DOMContentLoaded', function () {\n    var toggle = document.getElementById('navToggle');\n    var menu = document.getElementById('navMenu');\n\n    if (toggle && menu) {\n        toggle.addEventListener('click', function () {\n            menu.classList.toggle('show');\n        });\n\n        document.addEventListener('click', function (event) {\n            if (!toggle.contains(event.target) && !menu.contains(event.target)) {\n                menu.classList.remove('show');\n            }\n        });\n    }\n\n    var adminToggle = document.getElementById('adminSidebarToggle');\n    var adminSidebar = document.getElementById('adminSidebar');\n\n    if (adminToggle && adminSidebar) {\n        adminToggle.addEventListener('click', function () {\n            adminSidebar.classList.toggle('open');\n        });\n\n        document.addEventListener('click', function (event) {\n            if (adminSidebar.classList.contains('open') &&\n                !adminSidebar.contains(event.target) &&\n                !adminToggle.contains(event.target)) {\n                adminSidebar.classList.remove('open');\n            }\n        });\n\n        adminSidebar.querySelectorAll('a').forEach(function (link) {\n            link.addEventListener('click', function () {\n                adminSidebar.classList.remove('open');\n            });\n        });\n    }\n});",
}
